; overlap.asm -- chapter 13: a line moved with LDIR and with LDDR
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "overlap.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
ROW0    EQU $C200               ; three rows of a bitmap: 8 lines of 32 bytes each
ROW1    EQU ROW0 + 256
ROW2    EQU ROW1 + 256
blk_src EQU VARS + $10          ; showblk's working bytes, in the RAM
blk_rc  EQU VARS + $12
blk_k   EQU VARS + $14
blk_w   EQU VARS + $15
blk_h   EQU VARS + $16
; The same line of text three times, in a bitmap in the RAM; the second
; copy moved one cell to the right with LDIR, the third with LDDR (figure
; 13.1). showblk sends the bitmap to the VDP (chapter 10).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, ROW0
        ld de, ROW0 + 1
        ld (hl), 0
        ld bc, 768 - 1
        ldir                    ; the bitmap clear
        ld b, 1
        ld c, 0
        ld hl, lab0
        call puts
        ld b, 4
        ld c, 0
        ld hl, lab1
        call puts
        ld b, 7
        ld c, 0
        ld hl, lab2
        call puts
        ld hl, ROW0
        ld de, sample
        call text               ; the line, into row 0 of the bitmap
        ld hl, ROW1
        ld de, sample
        call text               ; the line, into row 1 of the bitmap
        ld hl, ROW2
        ld de, sample
        call text               ; the line, into row 2 of the bitmap
        ld hl, ROW1
        call fwd                ; row 1, with LDIR
        ld hl, ROW2
        call back               ; row 2, with LDDR
        ld hl, ROW0
        ld de, $2001            ; 32 bytes across, one row of cells
        ld a, 128
        ld b, 2
        ld c, 0
        call showblk
        ld hl, ROW1
        ld de, $2001            ; 32 bytes across, one row of cells
        ld a, 160
        ld b, 5
        ld c, 0
        call showblk
        ld hl, ROW2
        ld de, $2001            ; 32 bytes across, one row of cells
        ld a, 192
        ld b, 8
        ld c, 0
        call showblk
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; fwd: the row of the bitmap at HL moved one byte right, each line with LDIR
fwd:    ld a, 8                 ; eight lines
fw1:    push hl
        ld d, h
        ld e, l
        inc de                  ; DE: one byte on
        ld bc, 31
        ldir                    ; from the left end, forwards
        pop hl
        ld bc, 32
        add hl, bc              ; the next line
        dec a
        jr nz, fw1
        ret

; back: the row at HL moved one byte right with LDDR, from the right end
back:   ld a, 8
bk1:    push hl
        ld bc, 30
        add hl, bc              ; HL: the next to last byte
        ld d, h
        ld e, l
        inc de                  ; DE: the last
        ld bc, 31
        lddr                    ; from the right end, backwards
        pop hl
        ld bc, 32
        add hl, bc
        dec a
        jr nz, bk1
        ret

; text: the characters from DE (ending in 0) into the eight lines of a row
;       of the bitmap from HL, a byte across for each, from the BIOS's
;       character set
text:   ld a, (de)
        or a
        ret z
        push de
        push hl
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; the character x 8 ...
        ld bc, (CGTABL)
        add hl, bc              ; ... in the BIOS's set: its eight lines
        pop de                  ; DE: the bitmap
        push de
        ld b, 8
tx1:    ld a, (hl)
        ld (de), a
        inc hl
        ld a, e
        add a, 32
        ld e, a                 ; one line down the bitmap
        jr nc, tx2
        inc d
tx2:    djnz tx1
        pop hl
        inc hl                  ; the next byte across
        pop de
        inc de                  ; the next character
        jr text

; showblk: a bitmap in the RAM or the ROM, W bytes across and 8 x H lines
;          down, line after line, sent to the VDP as W x H character shapes
;          from code A, and those characters put on the screen in a block
;          whose top left is row B, column C. HL = the bitmap, D = W, E = H.
;          The display must be off (chapter 20).
showblk:
        ld (blk_src), hl
        ld (blk_rc), bc
        ld (blk_k), a
        ld a, d
        ld (blk_w), a
        ld a, e
        ld (blk_h), a
        ld a, (blk_k)
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; the shape of character K is at K x 8
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, (blk_w)
        ld e, a
        ld d, 0                 ; DE: W, from one line to the next
        ld hl, (blk_src)
        ld a, (blk_h)
        ld b, a                 ; B: the rows of cells left
sb1:    push bc
        push hl                 ; HL: the top line of this row of cells
        ld a, (blk_w)
        ld c, a                 ; C: the cells left in the row
sb2:    push hl
        ld b, 8
sb3:    ld a, (hl)              ; the cell's eight lines, a byte each
        out (VDP_DATA), a
        add hl, de              ; one line down
        djnz sb3
        pop hl
        inc hl                  ; the next cell: one byte across
        dec c
        jr nz, sb2
        pop hl
        ld b, 8
sb4:    add hl, de
        djnz sb4                ; eight lines down: the next row of cells
        pop bc
        djnz sb1
        ld bc, (blk_rc)
        ld a, (blk_k)
        ld d, a                 ; D: the next code
        ld a, (blk_h)
        ld e, a                 ; E: the rows left
sn1:    call at                 ; the name of (B, C)
        ld a, (blk_w)
        ld h, a
sn2:    ld a, d
        out (VDP_DATA), a
        inc d
        dec h
        jr nz, sn2
        inc b
        dec e
        jr nz, sn1
        ret

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
lab0:   db "The line:", 0
lab1:   db "Moved with LDIR, forwards:", 0
lab2:   db "Moved with LDDR, backwards:", 0
sample: db "Move this line one place right.", 0
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
